initial_condition:
with {
    the SUT being in the "initial state" and
    the SUT containing a list of Context Source Registrations (CSRs) providing latest information about some entities
    and the SUT containing a Context Source Registration Subscription (CSRS1)
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/csourceSubscriptions/{subscription_id}'
        method set to 'PATCH'
        Update Context Source Registration Subscription with subscription id set to '${subscription_id}' and subscription update fragment set to '${subscription_update_fragment}'
}

